		benchmark_decoposed: "groupby",
		benchmark_codes: `{"groupby.GroupByMethods.time_dtype_as_field": "class GroupByMethods:\\n    def time_dtype_as_field(self, dtype, method, application, ncols):\\n        self.as_field_method()\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass GroupByMethods:\\n    def setup(self, dtype, method, application, ncols):\\n        if method in method_blocklist.get(dtype, {}):\\n            raise NotImplementedError  # skip benchmark\\n    \\n        if ncols != 1 and method in [\\"value_counts\\", \\"unique\\"]:\\n            # DataFrameGroupBy doesn't have these methods\\n            raise NotImplementedError\\n    \\n        if application == \\"transformation\\" and method in [\\n            \\"describe\\",\\n            \\"head\\",\\n            \\"tail\\",\\n            \\"unique\\",\\n            \\"value_counts\\",\\n            \\"size\\",\\n        ]:\\n            # DataFrameGroupBy doesn't have these methods\\n            raise NotImplementedError\\n    \\n        if method == \\"describe\\":\\n            ngroups = 20\\n        elif method == \\"skew\\":\\n            ngroups = 100\\n        else:\\n            ngroups = 1000\\n        size = ngroups * 2\\n        rng = np.arange(ngroups).reshape(-1, 1)\\n        rng = np.broadcast_to(rng, (len(rng), ncols))\\n        taker = np.random.randint(0, ngroups, size=size)\\n        values = rng.take(taker, axis=0)\\n        if dtype == \\"int\\":\\n            key = np.random.randint(0, size, size=size)\\n        elif dtype in (\\"int16\\", \\"uint\\"):\\n            key = np.random.randint(0, size, size=size, dtype=dtype)\\n        elif dtype == \\"float\\":\\n            key = np.concatenate(\\n                [np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0]\\n            )\\n        elif dtype == \\"object\\":\\n            key = [\\"foo\\"] * size\\n        elif dtype == \\"datetime\\":\\n            key = date_range(\\"1/1/2011\\", periods=size, freq=\\"s\\")\\n    \\n        cols = [f\\"values{n}\\" for n in range(ncols)]\\n        df = DataFrame(values, columns=cols)\\n        df[\\"key\\"] = key\\n    \\n        if len(cols) == 1:\\n            cols = cols[0]\\n    \\n        if application == \\"transformation\\":\\n            self.as_group_method = lambda: df.groupby(\\"key\\")[cols].transform(method)\\n            self.as_field_method = lambda: df.groupby(cols)[\\"key\\"].transform(method)\\n        else:\\n            self.as_group_method = getattr(df.groupby(\\"key\\")[cols], method)\\n            self.as_field_method = getattr(df.groupby(cols)[\\"key\\"], method)", "groupby.GroupByMethods.time_dtype_as_group": "class GroupByMethods:\\n    def time_dtype_as_group(self, dtype, method, application, ncols):\\n        self.as_group_method()\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass GroupByMethods:\\n    def setup(self, dtype, method, application, ncols):\\n        if method in method_blocklist.get(dtype, {}):\\n            raise NotImplementedError  # skip benchmark\\n    \\n        if ncols != 1 and method in [\\"value_counts\\", \\"unique\\"]:\\n            # DataFrameGroupBy doesn't have these methods\\n            raise NotImplementedError\\n    \\n        if application == \\"transformation\\" and method in [\\n            \\"describe\\",\\n            \\"head\\",\\n            \\"tail\\",\\n            \\"unique\\",\\n            \\"value_counts\\",\\n            \\"size\\",\\n        ]:\\n            # DataFrameGroupBy doesn't have these methods\\n            raise NotImplementedError\\n    \\n        if method == \\"describe\\":\\n            ngroups = 20\\n        elif method == \\"skew\\":\\n            ngroups = 100\\n        else:\\n            ngroups = 1000\\n        size = ngroups * 2\\n        rng = np.arange(ngroups).reshape(-1, 1)\\n        rng = np.broadcast_to(rng, (len(rng), ncols))\\n        taker = np.random.randint(0, ngroups, size=size)\\n        values = rng.take(taker, axis=0)\\n        if dtype == \\"int\\":\\n            key = np.random.randint(0, size, size=size)\\n        elif dtype in (\\"int16\\", \\"uint\\"):\\n            key = np.random.randint(0, size, size=size, dtype=dtype)\\n        elif dtype == \\"float\\":\\n            key = np.concatenate(\\n                [np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0]\\n            )\\n        elif dtype == \\"object\\":\\n            key = [\\"foo\\"] * size\\n        elif dtype == \\"datetime\\":\\n            key = date_range(\\"1/1/2011\\", periods=size, freq=\\"s\\")\\n    \\n        cols = [f\\"values{n}\\" for n in range(ncols)]\\n        df = DataFrame(values, columns=cols)\\n        df[\\"key\\"] = key\\n    \\n        if len(cols) == 1:\\n            cols = cols[0]\\n    \\n        if application == \\"transformation\\":\\n            self.as_group_method = lambda: df.groupby(\\"key\\")[cols].transform(method)\\n            self.as_field_method = lambda: df.groupby(cols)[\\"key\\"].transform(method)\\n        else:\\n            self.as_group_method = getattr(df.groupby(\\"key\\")[cols], method)\\n            self.as_field_method = getattr(df.groupby(cols)[\\"key\\"], method)"}`,
