			'{"io.csv.ReadCSVCategorical.time_convert_post": "class ReadCSVCategorical:\\n    def time_convert_post(self, engine):\\n        read_csv(self.fname, engine=engine).apply(Categorical)\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ReadCSVCategorical:\\n    def setup(self, engine):\\n        N = 100000\\n        group1 = [\\"aaaaaaaa\\", \\"bbbbbbb\\", \\"cccccccc\\", \\"dddddddd\\", \\"eeeeeeee\\"]\\n        df = DataFrame(np.random.choice(group1, (N, 3)), columns=list(\\"abc\\"))\\n        df.to_csv(self.fname, index=False)", "io.csv.ReadCSVEngine.time_read_bytescsv": "class ReadCSVEngine:\\n    def time_read_bytescsv(self, engine):\\n        read_csv(self.data(self.BytesIO_input), engine=engine)\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ReadCSVEngine:\\n    def setup(self, engine):\\n        data = [\\"A,B,C,D,E\\"] + ([\\"1,2,3,4,5\\"] * 100000)\\n        self.StringIO_input = StringIO(\\"\\\\n\\".join(data))\\n        # simulate reading from file\\n        self.BytesIO_input = BytesIO(self.StringIO_input.read().encode(\\"utf-8\\"))", "io.csv.ReadCSVFloatPrecision.time_read_csv": "class ReadCSVFloatPrecision:\\n    def time_read_csv(self, sep, decimal, float_precision):\\n        read_csv(\\n            self.data(self.StringIO_input),\\n            sep=sep,\\n            header=None,\\n            names=list(\\"abc\\"),\\n            float_precision=float_precision,\\n        )\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ReadCSVFloatPrecision:\\n    def setup(self, sep, decimal, float_precision):\\n        floats = [\\n            \\"\\".join([random.choice(string.digits) for _ in range(28)])\\n            for _ in range(15)\\n        ]\\n        rows = sep.join([f\\"0{decimal}\\" + \\"{}\\"] * 3) + \\"\\\\n\\"\\n        data = rows * 5\\n        data = data.format(*floats) * 200  # 1000 x 3 strings csv\\n        self.StringIO_input = StringIO(data)", "io.csv.ReadCSVFloatPrecision.time_read_csv_python_engine": "class ReadCSVFloatPrecision:\\n    def time_read_csv_python_engine(self, sep, decimal, float_precision):\\n        read_csv(\\n            self.data(self.StringIO_input),\\n            sep=sep,\\n            header=None,\\n            engine=\\"python\\",\\n            float_precision=None,\\n            names=list(\\"abc\\"),\\n        )\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ReadCSVFloatPrecision:\\n    def setup(self, sep, decimal, float_precision):\\n        floats = [\\n            \\"\\".join([random.choice(string.digits) for _ in range(28)])\\n            for _ in range(15)\\n        ]\\n        rows = sep.join([f\\"0{decimal}\\" + \\"{}\\"] * 3) + \\"\\\\n\\"\\n        data = rows * 5\\n        data = data.format(*floats) * 200  # 1000 x 3 strings csv\\n        self.StringIO_input = StringIO(data)", "io.csv.ReadCSVParseSpecialDate.time_read_special_date": "class ReadCSVParseSpecialDate:\\n    def time_read_special_date(self, value, engine):\\n        read_csv(\\n            self.data(self.StringIO_input),\\n            engine=engine,\\n            sep=\\",\\",\\n            header=None,\\n            names=[\\"Date\\"],\\n            parse_dates=[\\"Date\\"],\\n        )\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ReadCSVParseSpecialDate:\\n    def setup(self, value, engine):\\n        count_elem = 10000\\n        data = self.objects[value] * count_elem\\n        self.StringIO_input = StringIO(data)", "io.csv.ToCSVIndexes.time_standard_index": "class ToCSVIndexes:\\n    def time_standard_index(self):\\n        self.df_standard_index.to_csv(self.fname)\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ToCSVIndexes:\\n    def setup(self):\\n        ROWS = 100000\\n        COLS = 5\\n        # For tests using .head(), create an initial dataframe with this many times\\n        # more rows\\n        HEAD_ROW_MULTIPLIER = 10\\n    \\n        self.df_standard_index = self._create_df(ROWS, COLS)\\n    \\n        self.df_custom_index_then_head = (\\n            self._create_df(ROWS * HEAD_ROW_MULTIPLIER, COLS)\\n            .set_index([\\"index1\\", \\"index2\\", \\"index3\\"])\\n            .head(ROWS)\\n        )\\n    \\n        self.df_head_then_custom_index = (\\n            self._create_df(ROWS * HEAD_ROW_MULTIPLIER, COLS)\\n            .head(ROWS)\\n            .set_index([\\"index1\\", \\"index2\\", \\"index3\\"])\\n        )", "io.csv.ToCSVMultiIndexUnusedLevels.time_single_index_frame": "class ToCSVMultiIndexUnusedLevels:\\n    def time_single_index_frame(self):\\n        self.df_single_index.to_csv(self.fname)\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ToCSVMultiIndexUnusedLevels:\\n    def setup(self):\\n        df = DataFrame({\\"a\\": np.random.randn(100_000), \\"b\\": 1, \\"c\\": 1})\\n        self.df = df.set_index([\\"a\\", \\"b\\"])\\n        self.df_unused_levels = self.df.iloc[:10_000]\\n        self.df_single_index = df.set_index([\\"a\\"]).iloc[:10_000]", "io.csv.ToCSVMultiIndexUnusedLevels.time_sliced_frame": "class ToCSVMultiIndexUnusedLevels:\\n    def time_sliced_frame(self):\\n        self.df_unused_levels.to_csv(self.fname)\\n\\ndef setup(*args, **kwargs):\\n    # This function just needs to be imported into each benchmark file to\\n    # set up the random seed before each function.\\n    # https://asv.readthedocs.io/en/latest/writing_benchmarks.html\\n    np.random.seed(1234)\\n\\nclass ToCSVMultiIndexUnusedLevels:\\n    def setup(self):\\n        df = DataFrame({\\"a\\": np.random.randn(100_000), \\"b\\": 1, \\"c\\": 1})\\n        self.df = df.set_index([\\"a\\", \\"b\\"])\\n        self.df_unused_levels = self.df.iloc[:10_000]\\n        self.df_single_index = df.set_index([\\"a\\"]).iloc[:10_000]"}',
