			'{"array.ArrowExtensionArray.time_to_numpy": "class ArrowExtensionArray:\\n    def time_to_numpy(self, dtype, hasna):\\n        self.arr.to_numpy()\\n\\n    def setup(self, dtype, hasna):\\n        N = 100_000\\n        if dtype == \\"boolean[pyarrow]\\":\\n            data = np.random.choice([True, False], N, replace=True)\\n        elif dtype == \\"float64[pyarrow]\\":\\n            data = np.random.randn(N)\\n        elif dtype == \\"int64[pyarrow]\\":\\n            data = np.arange(N)\\n        elif dtype == \\"string[pyarrow]\\":\\n            data = tm.rands_array(10, N)\\n        elif dtype == \\"timestamp[ns][pyarrow]\\":\\n            data = pd.date_range(\\"2000-01-01\\", freq=\\"s\\", periods=N)\\n        else:\\n            raise NotImplementedError\\n    \\n        arr = pd.array(data, dtype=dtype)\\n        if hasna:\\n            arr[::2] = pd.NA\\n        self.arr = arr", "array.ArrowStringArray.time_setitem_list": "class ArrowStringArray:\\n    def time_setitem_list(self, multiple_chunks):\\n        indexer = list(range(0, 50)) + list(range(-1000, 0, 50))\\n        self.array[indexer] = [\\"foo\\"] * len(indexer)\\n\\n    def setup(self, multiple_chunks):\\n        try:\\n            import pyarrow as pa\\n        except ImportError:\\n            raise NotImplementedError\\n        strings = tm.rands_array(3, 10_000)\\n        if multiple_chunks:\\n            chunks = [strings[i : i + 100] for i in range(0, len(strings), 100)]\\n            self.array = pd.arrays.ArrowStringArray(pa.chunked_array(chunks))\\n        else:\\n            self.array = pd.arrays.ArrowStringArray(pa.array(strings))", "array.ArrowStringArray.time_tolist": "class ArrowStringArray:\\n    def time_tolist(self, multiple_chunks):\\n        self.array.tolist()\\n\\n    def setup(self, multiple_chunks):\\n        try:\\n            import pyarrow as pa\\n        except ImportError:\\n            raise NotImplementedError\\n        strings = tm.rands_array(3, 10_000)\\n        if multiple_chunks:\\n            chunks = [strings[i : i + 100] for i in range(0, len(strings), 100)]\\n            self.array = pd.arrays.ArrowStringArray(pa.chunked_array(chunks))\\n        else:\\n            self.array = pd.arrays.ArrowStringArray(pa.array(strings))", "array.BooleanArray.time_from_bool_array": "class BooleanArray:\\n    def time_from_bool_array(self):\\n        pd.array(self.values_bool, dtype=\\"boolean\\")\\n\\n    def setup(self):\\n        self.values_bool = np.array([True, False, True, False])\\n        self.values_float = np.array([1.0, 0.0, 1.0, 0.0])\\n        self.values_integer = np.array([1, 0, 1, 0])\\n        self.values_integer_like = [1, 0, 1, 0]\\n        self.data = np.array([True, False, True, False])\\n        self.mask = np.array([False, False, True, False])", "array.IntegerArray.time_constructor": "class IntegerArray:\\n    def time_constructor(self):\\n        pd.arrays.IntegerArray(self.data, self.mask)\\n\\n    def setup(self):\\n        N = 250_000\\n        self.values_integer = np.array([1, 0, 1, 0] * N)\\n        self.data = np.array([1, 2, 3, 4] * N, dtype=\\"int64\\")\\n        self.mask = np.array([False, False, True, False] * N)", "array.IntervalArray.time_from_tuples": "class IntervalArray:\\n    def time_from_tuples(self):\\n        pd.arrays.IntervalArray.from_tuples(self.tuples)\\n\\n    def setup(self):\\n        N = 10_000\\n        self.tuples = [(i, i + 1) for i in range(N)]", "array.StringArray.time_from_list": "class StringArray:\\n    def time_from_list(self):\\n        pd.array(self.values_list, dtype=\\"string\\")\\n\\n    def setup(self):\\n        N = 100_000\\n        values = tm.rands_array(3, N)\\n        self.values_obj = np.array(values, dtype=\\"object\\")\\n        self.values_str = np.array(values, dtype=\\"U\\")\\n        self.values_list = values.tolist()"}',
